use vstd::prelude::*;

verus! {
    spec fn S(n: i8) -> i8
        decreases n,
    {
        if n % 2 == 0 {
            n / 2
        } else {
            -(n + 1) / 2
        }
    }

    fn solve(queries: Vec<(i8, i8)>) -> Vec<i8>
        requires
            queries.len() < 0x1_0000, // Ensure the length of queries is within bounds
        ensures
            result.len() == queries.len(),
            forall |i: nat| (i < queries.len() as nat) ==> (result[i] == S(queries[i].1) - S(queries[i].0 - 1)),
    {
        let mut results = Vec::with_capacity(queries.len());

        // Loop over each query
        for (l, r) in queries {
            // Calculate S(r)
            let s_r = S(r);

            // Calculate S(l - 1)
            let s_l_minus_1 = if l > 1 {
                S(l - 1)
            } else {
                0 // S(0) is defined as 0
            };

            // Calculate the sum for the range
            let sum = s_r - s_l_minus_1;
            results.push(sum);
        }

        results
    }
}

